"""The committed demo Proof Pack (generated by the Go engine) and its attack
scenarios, verified by the Python implementation."""

import base64
import copy
import json
import unittest

from proofengine import canon, merkle, note, pack, posture, sigs, tlog

from .helpers import DEMO_DATA

EXPECT = {"backdate": ["timestamps"], "replay": ["sequence", "timestamps"], "vendor_rewrite": ["sequence", "consistency", "witnesses"]}


def expand(genuine: dict, sc: dict) -> dict:
    """Rebuild an attack world's pack from its compact scenario (as the demo
    page and engine/internal/sample.Expand do)."""
    raw = base64.b64decode(sc["log_digests"])
    tree = merkle.Tree([tlog.leaf_hash(raw[i:i + 32]) for i in range(0, len(raw), 32)])
    size = note.parse_checkpoint(note.parse(sc["checkpoint"]).text).size
    v = copy.deepcopy(genuine)
    v["log"]["checkpoint"] = sc["checkpoint"]
    v["log"]["earlier_checkpoints"] = [
        {"checkpoint": e, "consistency_proof": [base64.b64encode(h).decode() for h in
                                                tree.consistency_proof(note.parse_checkpoint(note.parse(e).text).size, size)]}
        for e in sc["earlier_checkpoints"]]
    v["entries"] = []
    for e in sc["entries"]:
        src = genuine["entries"][e["ref"]] if "ref" in e else e
        v["entries"].append({"index": e["index"], "envelope": src["envelope"], "timestamps": src["timestamps"],
                             "inclusion_proof": [base64.b64encode(h).decode() for h in tree.inclusion_proof(e["index"], size)]})
    v["summary"] = sc["summary"]
    return v


class DemoPack(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = (DEMO_DATA / "pack.json").read_bytes()
        cls.trust = pack.parse_trust_policy((DEMO_DATA / "trust-policy.json").read_bytes())
        cls.value = canon.parse_container(cls.raw)

    def verify_value(self, v):
        return pack.verify(pack.parse(json.dumps(v).encode()), self.trust)

    def test_genuine_pack_verifies(self):
        p = pack.parse(self.raw)
        self.assertEqual(p.to_json(), self.raw, "serialization must match the Go writer byte for byte")
        r = pack.verify(p, self.trust)
        self.assertTrue(r.verified, r.text())
        self.assertEqual(len(r.gaps), 1)
        self.assertEqual((r.gaps[0]["device_number"], r.gaps[0]["from"], r.gaps[0]["to"]), (7, "2026-10-12", "2026-10-13"))
        self.assertEqual(canon.encode(r.computed), canon.encode(p.summary))

    def test_attack_scenarios(self):
        scenarios = canon.parse_container((DEMO_DATA / "scenarios.json").read_bytes())["scenarios"]
        self.assertEqual({s["id"] for s in scenarios}, set(EXPECT))
        for sc in scenarios:
            r = self.verify_value(expand(self.value, sc))
            self.assertEqual(r.failed_steps(), EXPECT[sc["id"]], sc["id"])

    def find(self, v, number, day):
        p = pack.parse(json.dumps(v).encode())
        att = next(e.evidence for e in p.entries if (lambda st: not st.is_posture and st.str("kind") == "attester" and st.int("device_number") == number)(
            posture.validate(e.evidence.envelope.payload)))
        aid = posture.validate(att.envelope.payload).str("attester")
        for i, e in enumerate(p.entries):
            st = posture.validate(e.evidence.envelope.payload)
            if st.is_posture and st.str("attester") == aid and st.str("observed_at").startswith(day):
                return i, aid
        raise AssertionError("not found")

    def test_flip_delete_and_hide(self):
        v = copy.deepcopy(self.value)
        i, aid = self.find(v, 7, "2026-10-14")
        env = v["entries"][i]["envelope"]
        st = canon.parse(sigs.decode_b64(env["payload"]))
        st["predicate"]["device"]["disk_encryption"] = "on"
        env["payload"] = base64.b64encode(canon.encode(st)).decode()
        self.assertEqual(self.verify_value(v).failed_steps(), ["signatures", "sequence", "timestamps", "inclusion", "gaps"])

        v = copy.deepcopy(self.value)
        del v["entries"][i]
        r = self.verify_value(v)
        self.assertEqual(r.failed_steps()[0], "sequence")
        self.assertIn("report #12 is missing", " ".join(r.step("sequence").problems))

        v = copy.deepcopy(self.value)
        v["summary"]["gaps"] = []
        r = self.verify_value(v)
        self.assertEqual(r.failed_steps(), ["gaps"])
        self.assertIn("hides a gap", " ".join(r.step("gaps").problems))

    def test_witness_quorum(self):
        n = note.parse(self.value["log"]["checkpoint"])
        for keep, ok in [(3, True), (2, True), (1, False), (0, False)]:
            v = copy.deepcopy(self.value)
            v["log"]["checkpoint"] = str(note.Note(n.text, n.sigs[:1 + keep]))
            self.assertEqual("witnesses" not in self.verify_value(v).failed_steps(), ok, keep)


if __name__ == "__main__":
    unittest.main()
